tbl3.DAILY_REWARD_CALCULATOR = function(arg1)
	if arg1 % 7 == 0 then
		local var1 = tbl4[arg1 / 7]
		return var1 or tbl4[#tbl4]
	end

	local var2 = math.clamp((if arg1 % 2 == 0 then 10 else 5) * arg1, 10, 250)
	return { writeLib = "Currency1", value = var2 }
end

