tbl3.CueUpgradeCostPerPoint = 400
tbl3.CueUpgradeStep = 1
tbl3.CueTotal = function(arg1)
	local var1 = tbl3.GetCue(arg1)
	local num1 = 0
	for k1, v1 in tbl3.CueStatOrder, nil do
		num1 = num1 + (tonumber(var1[v1]) or 0)
	end

	return num1
end

tbl3.CueMaxLevel = function(arg1)
	local var1 = arg1
	local var2 = tbl3.CueUpgradeLevelOverrides[var1 or tbl3.DefaultCue]
	if typeof(var2) == "number" then
		return (math.clamp(math.floor(var2), 0, tbl3.CueUpgradeMaxLevel))
	end

	return (math.clamp(math.floor(tbl3.CueTotal(arg1) / 10), 0, tbl3.CueUpgradeMaxLevel))
end

tbl3.CueUpgradeCost = function(arg1, arg2)
	local var2 = math.floor(arg2) + 1
	if tbl3.CueMaxLevel(arg1) < var2 then
		return nil
	end

	return tbl3.CueTotal(arg1) * tbl3.CueUpgradeCostPerPoint * var2
end

