	if var3 <= 0 then
		return "Free"
	end

	local var4 = var3
	return var1:Separate(var4)
end

tbl3.VenueUnlockWins = 5
tbl3.BotUnlockWins = 1
tbl3.BotLevelIndex = function(arg1)
	for k1, v1 in tbl3.Bots.Levels, nil do
		if v1.Id ~= arg1 then
			continue
		end

		return k1
	end

	return nil
end

tbl3.PreviousBotLevel = function(arg1)
	local var2 = tbl3.BotLevelIndex(arg1)
	if not var2 then
		return nil
	end

	return tbl3.Bots.Levels[var2 - 1]
end

tbl3.IsBotUnlocked = function(arg1, arg2)
	local var2 = tbl3.BotLevelIndex(arg2)
	if not var2 then
		return false
	end

	local var4 = tbl3.Bots.Levels[var2 - 1]
	if not var4 then
		return true
	end

	if typeof(arg1) ~= "table" then
		return false
	end

	if tbl3.BotUnlockWins <= (arg1[var4.Id] or 0) then
		return true
	end

	for i1 = var2, #tbl3.Bots.Levels do
		if 0 >= (arg1[tbl3.Bots.Levels[i1].Id] or 0) then
			continue
		end

		return true
	end

	return false
end

